const project = $('Load Project Data').first().json;
const prompt = $('Load Safety Prompt').first().json;
const executionId = $input.first().json.id;

const briefing = typeof project.briefing === 'string' ? JSON.parse(project.briefing) : (project.briefing || {});
const design = typeof project.design_option === 'string' ? JSON.parse(project.design_option) : (project.design_option || {});
const costs = typeof project.cost_estimate === 'string' ? JSON.parse(project.cost_estimate) : (project.cost_estimate || {});
const plan = typeof project.project_plan === 'string' ? JSON.parse(project.project_plan) : (project.project_plan || {});
const trades = Array.isArray(project.trade_assignments) ? project.trade_assignments : [];

const phasesText = (Array.isArray(plan.phases) ? plan.phases : []).map(p => `${p.order || '?'}. ${p.phase_name || p.name} (${p.duration_weeks || '?'} sem, especialidad: ${p.specialty || '?'})`).join('\n');
const tradesText = trades.map(t => `- ${t.trade_type}: ${t.scope_description || 'pendiente'}`).join('\n');
const objectives = Array.isArray(briefing.objectives) ? briefing.objectives.join('; ') : '';
const constraints = Array.isArray(briefing.constraints) ? briefing.constraints.join('; ') : '';
const pemTotal = costs.total_estimated || 'no estimado';
const durationWeeks = plan.total_duration_days ? Math.round(plan.total_duration_days / 7) : '?';

const prompt_user = `Genera el documento de Seguridad y Salud para este proyecto.

PROYECTO: ${project.project_name}
Tipo: ${project.project_type} | Área: ${project.property_area_m2} m² | Tipo propiedad: ${project.property_type || 'no especificado'}
Ubicación: ${project.location_address || ''}, ${project.location_city}, ${project.location_province}
PEM estimado: ${pemTotal}€
Duración: ${durationWeeks} semanas

DISEÑO ELEGIDO: ${design.title || 'no especificado'}
${design.description ? 'Descripción: ' + design.description : ''}

GREMIOS:
${tradesText || 'No definidos aún'}

FASES DEL PLAN:
${phasesText || 'Plan no generado'}

OBJETIVOS TÉCNICOS: ${objectives || 'no especificados'}
RESTRICCIONES DETECTADAS: ${constraints || 'ninguna'}

Tipo de inmueble: ${project.property_type}. Año del edificio: PROBABLEMENTE pre-2002 (común en reforma) — evaluar amianto en bajantes/cubierta antes de demolición.

Genera el EBSS o PSS según RD 1627/1997 art. 4 (decide tú según los datos del proyecto). Output JSON exacto según el esquema.`;

// === STUDIO PROFILE INJECTION (B24) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_priorities=_safeStudio(_studio.priorities)||[];
const _SP_SAFE_LINES=[];
_SP_SAFE_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'.');
_SP_SAFE_LINES.push('PRIORIDADES (la #1 deberia ser seguridad estructural; usa estas para ponderar riesgos):');
(_priorities||[]).forEach(p=>_SP_SAFE_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')));
const _SP_SAFE=_SP_SAFE_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
const systemPromptToUse = _SP_SAFE + '\n\n' + ((prompt && prompt.content) ? prompt.content : 'Eres CSS y generas EBSS/PSS según RD 1627/1997. Responde solo JSON.');

return [{ json: {
  execution_id: executionId,
  project_id: project.id,
  project_name: project.project_name,
  prompt_system: systemPromptToUse,
  prompt_user,
  model: 'gpt-4o',
  temperature: 0.2,
  agent_name: 'agent_safety_plan'
}}];

const llm = $input.first().json;
const project = $('Load Project Data').first().json;
const built = $('Build Safety Prompt').first().json;
const text = llm.text || '';

let parsed = {};
let parseError = null;

try {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
  else throw new Error('No JSON found in LLM response');
} catch (e) {
  parseError = e.message;
  parsed = {
    document_type: 'EBSS',
    document_type_justification: 'Generación automática fallida — usar plantilla manual',
    project_summary: project.project_name + ' — revisar manualmente',
    applicable_regulations: ['RD 1627/1997', 'Ley 31/1995 PRL'],
    phases_with_risks: [],
    general_collective_protections: [],
    general_epis: [],
    emergency_protocol: {},
    hygiene_facilities: [],
    simultaneous_activities: [],
    training_required: [],
    medical_surveillance: '',
    recommendations_to_architect: ['Generar manualmente — error en LLM: ' + parseError]
  };
}

return [{ json: {
  execution_id: built.execution_id,
  project_id: project.id,
  project_name: project.project_name,
  document_type: parsed.document_type || 'EBSS',
  content_json: JSON.stringify(parsed),
  parse_error: parseError
}}];

const parse = $('Parse Safety Response').first().json;
const project = $('Load Project Data').first().json;
const draft = $input.first().json;
const content = JSON.parse(parse.content_json);

const lines = [];
lines.push(content.document_type + ' — ' + project.project_name);
lines.push('');
lines.push('Tipo de documento: ' + content.document_type);
lines.push('Justificación: ' + (content.document_type_justification || ''));
lines.push('');
lines.push('1. RESUMEN DEL PROYECTO');
lines.push(content.project_summary || '');
lines.push('Cliente: ' + (project.client_name || '?'));
lines.push('Ubicación: ' + [project.location_address, project.location_city, project.location_province].filter(Boolean).join(', '));
lines.push('Superficie: ' + (project.property_area_m2 || '?') + ' m²');
lines.push('');
lines.push('2. NORMATIVA APLICABLE');
(content.applicable_regulations || []).forEach(r => lines.push('  • ' + r));
lines.push('');
lines.push('3. RIESGOS POR FASE');
(content.phases_with_risks || []).forEach(ph => {
  lines.push('--- Fase ' + (ph.phase_order || '?') + ': ' + (ph.phase_name || '?') + ' ---');
  lines.push('Trabajadores simultáneos estimados: ' + (ph.workers_simultaneous || '?'));
  lines.push('');
  (ph.specific_risks || []).forEach(r => {
    lines.push('  RIESGO: ' + r.risk);
    lines.push('    Severidad: ' + r.severity + ' | Probabilidad: ' + r.probability);
    lines.push('    Medidas preventivas:');
    (r.preventive_measures || []).forEach(m => lines.push('      - ' + m));
    lines.push('    Protecciones colectivas:');
    (r.collective_protections || []).forEach(p => lines.push('      - ' + p));
    lines.push('    EPIs requeridos:');
    (r.epis_required || []).forEach(e => lines.push('      - ' + e));
    lines.push('');
  });
});
lines.push('4. PROTECCIONES COLECTIVAS GENERALES');
(content.general_collective_protections || []).forEach(p => lines.push('  • ' + p));
lines.push('');
lines.push('5. EPIs GENERALES OBLIGATORIOS');
(content.general_epis || []).forEach(e => lines.push('  • ' + e));
lines.push('');
lines.push('6. PROTOCOLO DE EMERGENCIA');
const ep = content.emergency_protocol || {};
lines.push('Botiquín ubicado en: ' + (ep.first_aid_kit_location || 'a definir'));
lines.push('Contactos de emergencia: ' + ((ep.emergency_contacts || []).join(', ') || '112'));
lines.push('Ruta de evacuación: ' + (ep.evacuation_route || 'a definir'));
lines.push('Hospital más cercano: ' + (ep.nearest_hospital || 'a definir'));
lines.push('');
lines.push('7. INSTALACIONES DE HIGIENE');
(content.hygiene_facilities || []).forEach(f => lines.push('  • ' + f));
lines.push('');
if ((content.simultaneous_activities || []).length > 0) {
  lines.push('8. CONCURRENCIA DE ACTIVIDADES (art. 24 LPRL)');
  content.simultaneous_activities.forEach(s => {
    lines.push('  • ' + s.phase_a + ' + ' + s.phase_b + ' → ' + s.coordination_required);
  });
  lines.push('');
}
lines.push('9. FORMACIÓN PRL REQUERIDA');
(content.training_required || []).forEach(t => lines.push('  • ' + t));
lines.push('');
lines.push('10. VIGILANCIA MÉDICA');
lines.push(content.medical_surveillance || 'según convenio');
lines.push('');
lines.push('11. RECOMENDACIONES AL ARQUITECTO');
(content.recommendations_to_architect || []).forEach(r => lines.push('  • ' + r));
lines.push('');
lines.push('---');
lines.push('Documento generado por ArquitAI — debe ser revisado, completado y firmado por el Coordinador de Seguridad y Salud designado.');

return [{ json: {
  safety_plan_id: draft.id,
  doc_title: content.document_type + ' - ' + project.project_name,
  doc_body: lines.join('\n'),
  project_id: project.id,
  execution_id: $('Build Safety Prompt').first().json.execution_id
}}];
